const BASIS =
  "Every line value is computed once, when the entry is logged, in integer cents: hours times the rate, or quantity times the unit cost, rounded half-up to the nearest cent. " +
  "Totals are the sums of those stored line values, so a total can never drift from the lines it is made of. Hours are summed as integer hundredths. " +
  "Currencies are never added together: this server holds no exchange rate, so one number over a EUR card and a GBP one would be an invented number.";

const ROUNDING =
  "Rounding rule: a labor line is hours x hourly rate, a materials line is quantity x unit cost, each rounded half-up to the nearest cent at log time and stored; totals are the sums of the rounded lines.";

/* ------------------------------------------------------------- view helpers */

function laborJson(e: LaborEntry, currency: string) {
  return {
    date: e.date, worker: e.worker, hours: e.hours, rate_cents: e.rate_cents,
    rate: money(e.rate_cents, currency), value_cents: e.value_cents, value: money(e.value_cents, currency),
    note: e.note ?? null,
  };
}

function materialJson(e: MaterialEntry, currency: string) {
  return {
    date: e.date, item: e.item, qty: e.qty, unit_cost_cents: e.unit_cost_cents,
    unit_cost: money(e.unit_cost_cents, currency), value_cents: e.value_cents, value: money(e.value_cents, currency),
    note: e.note ?? null,
  };
}

function cardSummary(c: Card) {
  const labor = laborTotalCents(c.labor);
  const materials = materialsTotalCents(c.materials);
  return {
    id: c.id, client: c.client, site: c.site, status: c.status,
    scheduled_date: c.scheduled_date, currency: c.currency,
    labor_entries: c.labor.length, material_entries: c.materials.length,
    hours: totalHoursHundredths(c.labor) / 100,
    labor_total_cents: labor, labor_total: money(labor, c.currency),
    materials_total_cents: materials, materials_total: money(materials, c.currency),
    grand_total_cents: labor + materials, grand_total: money(labor + materials, c.currency),
    updated: c.updated,
  };
}

function cardDetail(c: Card) {
  return {
    ...cardSummary(c),
    description: c.description,
    note: c.note ?? null,
    created: c.created,
    history: c.history,
    labor: c.labor.map((e) => laborJson(e, c.currency)),
    materials: c.materials.map((e) => materialJson(e, c.currency)),
  };
}

/** Currencies are totalled apart, never across. */
function totalsByCurrency(cards: Card[]) {
  const map = new Map<string, { labor_cents: number; materials_cents: number; hours_hundredths: number; cards: number }>();
  for (const c of cards) {
    const t = map.get(c.currency) ?? { labor_cents: 0, materials_cents: 0, hours_hundredths: 0, cards: 0 };
    t.cards += 1;
    t.labor_cents += laborTotalCents(c.labor);
    t.materials_cents += materialsTotalCents(c.materials);
    t.hours_hundredths += totalHoursHundredths(c.labor);
    map.set(c.currency, t);
  }
  return [...map.entries()].map(([currency, t]) => ({
    currency, cards: t.cards, hours: t.hours_hundredths / 100,
    labor_cents: t.labor_cents, labor: money(t.labor_cents, currency),
    materials_cents: t.materials_cents, materials: money(t.materials_cents, currency),
    total_cents: t.labor_cents + t.materials_cents, total: money(t.labor_cents + t.materials_cents, currency),
  }));
}

function freeTierNote(): string | null {
  if (gate.isPro()) return null;
  return `Free tier: ${getCards().filter(isActive).length} of ${FREE_ACTIVE_CARDS} active job cards.`;
}

/* ------------------------------------------------------------------ helpers */

function entryGuards(c: Card, date: string): void {
  if (!acceptsEntries(c.status)) {
    const reached = c.history.find((h) => h.status === c.status);
    throw new Error(
      `${c.id} is ${c.status}${reached ? ` since ${reached.date}` : ""}. Logging against it now would change a job that is no longer on the board. ` +
      `Open a second card for the extra work. Nothing was written.`,
    );
  }
  const now = today();
  if (date > now) throw new Error(`the entry is dated ${date}, which is after today (${now}). Work cannot have been done yet. Nothing was written.`);
  if (c.labor.length >= MAX_ENTRIES) throw new Error(`${c.id} already carries ${MAX_ENTRIES} entries, which is the ceiling. Nothing was written.`);
}

function esc(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

const SIGN_MD = `| | |\n| --- | --- |\n| Client signature: ______________________________ | Date: ______________ |\n| Name: _________________________________________ | |`;

