server.registerTool("job_card_update_status", {
  title: "Move a job card one step",
  description: "Move one job card exactly one step: open, in_progress, done, invoiced, archived, stamping the date and an optional note into its history. A skipped or backwards step is refused and nothing is written. Archiving a finished job frees a free-tier slot.",
  inputSchema: {
    card: cardArg,
    status: str("status", 20).describe(`The next step for this card: ${FLOW.join(", ")}. in-progress is accepted too`),
    date: str("date", 10).optional().describe("The date to stamp the step with, YYYY-MM-DD. Default today"),
    note: str("note", MAX_TEXT).optional(),
  },
}, async (a) => {
  try {
    const date = a.date ? checkDate(a.date, "date") : today();
    const target = normalizeStatus(a.status);
    if (!target) throw new Error(`"${a.status}" is not a status a job card has. The flow is ${FLOW.join(", ")}. Nothing was written.`);
    const out = await locked(() => {
      const list = getCards();
      const c = resolveCard(list, a.card);
      const want = nextStatus(c.status);
      if (target === c.status) throw new Error(`${c.id} is already ${c.status}. Nothing was written.`);
      if (target !== want) {
        throw new Error(
          want === null
            ? `${c.id} is archived, the end of the flow, and cannot move. Nothing was written.`
            : `${c.id} is ${c.status} and a job card moves exactly one step at a time, so the only step from here is ${want}. ` +
              `Asked for ${target}. The flow is ${FLOW.join(" to ")}. Nothing was written.`,
        );
      }
      const last = c.history[c.history.length - 1];
      if (last && date < last.date) {
        throw new Error(`the last step on ${c.id} is stamped ${last.date} and this one is dated ${date}. A step cannot be dated before the step before it. Nothing was written.`);
      }
      c.history.push({ status: target, date, note: a.note, at: new Date().toISOString() });
      c.status = target;
      c.updated = new Date().toISOString();
      setCards(list);
      return c;
    });
    const notes: string[] = [];
    if (out.status === "done") notes.push("The card is done: no more labor or materials can be logged against it. job_card_print renders it for the client's signature.");
    if (out.status === "archived") notes.push("The card is archived and no longer counts against the free tier. Its record is kept.");
    return json({ card: cardSummary(out), history: out.history, notes });
  } catch (e) { return fail((e as Error).message); }
});

server.registerTool("job_card_list", {
  title: "List job cards",
  description: "List job cards newest first: client, site, status, hours logged, and the labor, materials and grand totals in cents. Filter by status and by client. Totals are kept per currency, never mixed.",
  inputSchema: {
    status: str("status", 20).optional().describe(`Only cards at this status: ${FLOW.join(", ")}`),
    client: str("client", MAX_NAME).optional().describe("Only cards whose client contains this text, case-insensitive"),
  },
}, async (a) => {
  try {
    let status: Status | null = null;
    if (a.status !== undefined) {
      status = normalizeStatus(a.status);
      if (!status) throw new Error(`"${a.status}" is not a status a job card has. The flow is ${FLOW.join(", ")}.`);
    }
    let list = getCards();
    if (status) list = list.filter((c) => c.status === status);
    if (a.client) {
      const needle = a.client.trim().toLowerCase();
      list = list.filter((c) => c.client.toLowerCase().includes(needle));
    }
    list = [...list].sort((x, y) => (x.created === y.created ? y.id.localeCompare(x.id) : x.created < y.created ? 1 : -1));
    const notes: string[] = [];
    const free = freeTierNote();
    if (free) notes.push(free);
    return json({
      count: list.length,
      active: getCards().filter(isActive).length,
      cards: list.map(cardSummary),
      totals: totalsByCurrency(list),
      notes, basis: BASIS,
    });
  } catch (e) { return fail((e as Error).message); }
});

server.registerTool("job_card_get", {
  title: "Read one job card with its running totals",
  description: "Read one job card in full by JC number or client: every labor entry and every material used, the hours per worker, and the running totals -- labor, materials and grand total -- as integer cents with formatted amounts. Reads only.",
  inputSchema: {
    card: cardArg,
  },
}, async (a) => {
  try {
    const list = getCards();
    const c = findCard(list, a.card);
    if (!c) throw new Error(`no job card matches "${a.card}". Known: ${list.map((x) => `${x.id} (${x.client})`).join(", ") || "none"}.`);
    const perWorker = new Map<string, number>();
    for (const e of c.labor) perWorker.set(e.worker, (perWorker.get(e.worker) ?? 0) + Math.round(e.hours * 100));
    return json({
      ...cardDetail(c),
      hours_by_worker: [...perWorker.entries()].map(([worker, h]) => ({ worker, hours: h / 100 })),
      basis: BASIS,
    });
  } catch (e) { return fail((e as Error).message); }
});

